#include <iostream>
using namespace std;

void printBar(int length) {
    if (length <= 0) {
        cout << "(nothing to draw)" << endl;
        return;                 // leave now, with no value
    }
    for (int i = 1; i <= length; i++) {
        cout << "*";
    }
    cout << endl;
}

int main() {
    printBar(9);
    printBar(0);
    printBar(-4);
    return 0;
}

