#include <iostream>
using namespace std;

int digitSum(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

int reverseDigits(int n) {
    int result = 0;
    while (n > 0) {
        result = result * 10 + n % 10;
        n /= 10;
    }
    return result;
}

long long factorial(int n) {
    long long product = 1;
    for (int i = 2; i <= n; i++) {
        product *= i;
    }
    return product;
}

bool isPrime(int n) {
    if (n < 2) {
        return false;       // 0, 1 and negatives are not prime
    }
    for (int i = 2; i < n; i++) {
        if (n % i == 0) {
            return false;   // found a divisor, so stop
        }
    }
    return true;            // nothing divided it
}

int main() {
    cout << boolalpha;
    cout << "digitSum(4071)      = " << digitSum(4071) << endl;
    cout << "reverseDigits(4071) = " << reverseDigits(4071) << endl;
    cout << "factorial(15)       = " << factorial(15) << endl;
    cout << "isPrime(91)         = " << isPrime(91) << endl;
    cout << "isPrime(97)         = " << isPrime(97) << endl;
    return 0;
}

